import React, { useState, useEffect, useRef } from 'react';
import MapDisplay from './MapDisplay';
import './App.css';

export default function App() {
  // --- Dynamic rows state ---
  const [rows, setRows] = useState([
    { customerId: '', category: '', weightType: '', storageId: '' }
  ]);

  // data fetched from APIs
  const [customers, setCustomers] = useState([]);
  const [storages, setStorages] = useState([]);
  const [categories, setCategories] = useState([]);
  const [weightOptions] = useState(['Light', 'Medium', 'Heavy']);

  const suggestionRef = useRef(null);

  useEffect(() => {
    // fetch customers
    fetch('http://127.0.0.1:5000/customers')
      .then(res => res.json())
      .then(data => setCustomers(data.customers))
      .catch(console.error);

    // fetch storages
    fetch('http://127.0.0.1:5000/storages')
      .then(res => res.json())
      .then(data => setStorages(data.storages))
      .catch(console.error);

    // fetch categories
    fetch('http://127.0.0.1:5000/categories')
      .then(res => res.json())
      .then(data => setCategories(data.categories))
      .catch(console.error);

    // click outside to close any suggestion panels
    const onClickOutside = e => {
      if (suggestionRef.current && !suggestionRef.current.contains(e.target)) {
        // nothing special here since selects are native
      }
    };
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  const addRow = () => {
    setRows([...rows, { customerId: '', category: '', weightType: '', storageId: '' }]);
  };

  const removeRow = idx => {
    const updated = rows.filter((_, i) => i !== idx);
    setRows(updated.length ? updated : [{ customerId: '', category: '', weightType: '', storageId: '' }]);
  };

  const handleChange = (idx, field, value) => {
    const updated = [...rows];
    updated[idx][field] = value;
    setRows(updated);
  };

  const handleSubmit = async () => {
    const payload = rows.map(r => ({
      customer: r.customerId,
      category: r.category,
      weight: r.weightType,
      storage: r.storageId
    }));
    try {
      const res = await fetch('http://127.0.0.1:5000/optimize', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: payload })
      });
      const json = await res.json();
      console.log('Optimized', json);
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div className="p-6 max-w-5xl mx-auto">
      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Delivery Optimizer</h1>
        <button className="bg-blue-600 text-white px-4 py-2 rounded">+ New Route</button>
      </div>

      {/* Grid-form per photo style */}
      <div className="grid grid-cols-4 gap-4 font-semibold mb-2">
        <div className="flex items-center">
          <button onClick={addRow} className="text-green-600 text-xl mr-2">+</button>
          Customer
        </div>
        <div className="flex items-center">
          <button onClick={addRow} className="text-green-600 text-xl mr-2">+</button>
          Category
        </div>
        <div>Weight</div>
        <div>Storage</div>
      </div>

      {rows.map((row, idx) => (
        <div key={idx} className="grid grid-cols-4 gap-4 items-center mb-2">
          {/* Customer Select */}
          <select
            value={row.customerId}
            onChange={e => handleChange(idx, 'customerId', e.target.value)}
            className="border rounded p-2"
          >
            <option value="">Select</option>
            {customers.map(c => (
              <option key={c.CustomerID} value={c.CustomerID}>{c.CustomerName}</option>
            ))}
          </select>

          {/* Category Select */}
          <select
            value={row.category}
            onChange={e => handleChange(idx, 'category', e.target.value)}
            className="border rounded p-2"
          >
            <option value="">Select</option>
            {categories.map(cat => (
              <option key={cat.id} value={cat.id}>{cat.name}</option>
            ))}
          </select>

          {/* Weight Select */}
          <select
            value={row.weightType}
            onChange={e => handleChange(idx, 'weightType', e.target.value)}
            className="border rounded p-2"
          >
            <option value="">Select</option>
            {weightOptions.map(w => (
              <option key={w} value={w}>{w}</option>
            ))}
          </select>

          {/* Storage Select + remove */}
          <div className="flex items-center">
            <select
              value={row.storageId}
              onChange={e => handleChange(idx, 'storageId', e.target.value)}
              className="border rounded p-2 flex-grow"
            >
              <option value="">Select</option>
              {storages.map(s => (
                <option key={s.StorageID} value={s.StorageID}>{s.StorageName}</option>
              ))}
            </select>
            <button onClick={() => removeRow(idx)} className="text-red-500 text-xl ml-2">×</button>
          </div>
        </div>
      ))}

      <div className="mt-4">
        <button
          onClick={handleSubmit}
          className="bg-green-600 text-white px-6 py-2 rounded"
        >Submit for Optimization</button>
      </div>

      {/* Map display at bottom */}
      <div className="mt-6 h-96">
        <MapDisplay
          routeData={[] /* replace with optimized coords */}
          defaultCenter={[0, 0]}
          zoom={12}
        />
      </div>
    </div>
  );
}
